    {"type":"MCQ","outcome_code":"10-CBSE-SOC-GEO-RD-01","difficulty":"EASY","cognitive_level":"REMEMBER","marks":1,"question":"Resources are the result of an interaction between nature, technology and:","options":["population","institutions","language","weather"],"answer":"institutions","explanation":"Three-way interaction."},
    {"type":"MCQ","outcome_code":"10-CBSE-SOC-GEO-RD-01","difficulty":"EASY","cognitive_level":"UNDERSTAND","marks":1,"question":"Which best illustrates that a 'resource' is socially constructed?","options":["fish in a river","oil that requires refining technology to be useful","sunshine","water"],"answer":"oil that requires refining technology to be useful","explanation":"Tech transforms raw matter into resource."},
    {"type":"MCQ","outcome_code":"10-CBSE-SOC-GEO-RD-02","difficulty":"EASY","cognitive_level":"REMEMBER","marks":1,"question":"Renewable resources are further divided into:","options":["continuous and biological","stock and reserves","biotic and abiotic","national and international"],"answer":"continuous and biological","explanation":"Continuous (sunlight) vs biological (forests)."},
