    {"type":"MCQ","outcome_code":"10-CBSE-SOC-CIV-PS-06","difficulty":"MEDIUM","cognitive_level":"APPLY","marks":2,"question":"Reserved Lok Sabha seats for SC and ST is an example of:","options":["horizontal sharing","vertical sharing","sharing among social groups","sharing among parties"],"answer":"sharing among social groups","explanation":"Group-level."},
