    {"type":"FILL_BLANK","outcome_code":"10-CBSE-SOC-CIV-PS-01","difficulty":"EASY","cognitive_level":"REMEMBER","marks":1,"question":"The Flemish region of Belgium is mostly ____ -speaking.","answer":"Dutch","explanation":"Flemish = Dutch."},
